import { existsSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const scriptDirectory = dirname(fileURLToPath(import.meta.url));
export const repositoryRoot = resolve(scriptDirectory, "..");
export const descriptorRelativePath = "observer/protocol/generated/enforce-contract.json";
export const enforceHeader =
  "// Generated by npm run protocol:generate from observer/protocol/enforce-contract.ts. Do not edit.";

const targetNames = ["runtime", "workbench"];
const targetToDescriptorName = { runtime: "game", workbench: "workbench" };
const expectedOutputPaths = {
  runtime: "observer/addon/Scripts/Game/ReforgerForgeObserver/RFO_ObserverProtocol.c",
  workbench: "observer/workbench-addon/Scripts/WorkbenchGame/EnfusionMCP/EMCP_WB_ObserverProtocol.c",
};
const expectedClassNames = {
  runtime: "RFO_ObserverProtocol",
  workbench: "EMCP_WB_ObserverProtocol",
};

function toAbsolute(root, relativePath) {
  return join(root, ...relativePath.split("/"));
}

function normalizeLf(value) {
  return value.replaceAll("\r\n", "\n").replaceAll("\r", "\n");
}

function asRecord(value, label, failures) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    failures.push(`${label} must be an object`);
    return null;
  }
  return value;
}

function asString(value, label, failures) {
  if (typeof value !== "string") {
    failures.push(`${label} must be a string`);
    return null;
  }
  return value;
}

function asArray(value, label, failures) {
  if (!Array.isArray(value)) {
    failures.push(`${label} must be an array`);
    return null;
  }
  return value;
}

function escapeEnforceStringLiteral(value) {
  if (value.includes("\0")) throw new Error("Enforce string literals must not contain NUL");
  let rendered = "";
  for (const character of value) {
    const code = character.codePointAt(0);
    if (code === undefined) throw new Error("Could not read Enforce string character");
    if (character === "\\") rendered += "\\\\";
    else if (character === "\"") rendered += "\\\"";
    else if (character === "\r") rendered += "\\r";
    else if (character === "\n") rendered += "\\n";
    else if (character === "\t") rendered += "\\t";
    else if (code < 0x20 || code === 0x7f) rendered += `\\x${code.toString(16).padStart(2, "0")}`;
    else rendered += character;
  }
  return rendered;
}

function expandScientificNotation(value) {
  if (!/[eE]/.test(value)) return value;
  const match = /^(-?)(\d+)(?:\.(\d*))?[eE]([+-]?\d+)$/.exec(value);
  if (!match) throw new Error(`Could not render Enforce float ${value}`);
  const [, sign, whole, fraction = "", exponentText] = match;
  const digits = `${whole}${fraction}`;
  const decimalIndex = whole.length + Number(exponentText);
  if (decimalIndex <= 0) return `${sign}0.${"0".repeat(-decimalIndex)}${digits}`;
  if (decimalIndex >= digits.length) return `${sign}${digits}${"0".repeat(decimalIndex - digits.length)}`;
  return `${sign}${digits.slice(0, decimalIndex)}.${digits.slice(decimalIndex)}`;
}

function renderNumber(value, kind) {
  if (!Number.isFinite(value)) throw new Error("Enforce numeric literals must be finite");
  if (kind === "int") {
    if (!Number.isSafeInteger(value)) throw new Error("Enforce integer literals must be safe integers");
    return String(value);
  }
  if (kind !== "float" || Math.abs(value) > 3.402823466e38) {
    throw new Error("Enforce float literal is unsupported");
  }
  const decimal = expandScientificNotation(String(Object.is(value, -0) ? 0 : value));
  return decimal.includes(".") ? decimal : `${decimal}.0`;
}

export function renderDescriptorEnforceClass(target) {
  const strings = target.strings ?? [];
  const numbers = target.numbers ?? [];
  return [
    enforceHeader,
    `class ${target.className}`,
    "{",
    ...strings.map((entry) => `\tstatic const string ${entry.field} = "${escapeEnforceStringLiteral(entry.value)}";`),
    ...numbers.map((entry) => `\tstatic const ${entry.kind} ${entry.field} = ${renderNumber(entry.value, entry.kind)};`),
    "}",
    "",
  ].join("\n");
}

function validateTargetDescriptor(target, targetName, descriptor, failures) {
  const targetObject = asRecord(target, `targets.${targetName}`, failures);
  if (!targetObject) return null;
  const className = asString(targetObject.className, `targets.${targetName}.className`, failures);
  const outputPath = asString(targetObject.outputPath, `targets.${targetName}.outputPath`, failures);
  const strings = asArray(targetObject.strings, `targets.${targetName}.strings`, failures);
  const numbers = asArray(targetObject.numbers, `targets.${targetName}.numbers`, failures);
  if (!className || !outputPath || !strings || !numbers) return null;
  if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(className)) failures.push(`targets.${targetName}.className is unsupported`);
  if (!/^[A-Za-z0-9._/-]+$/.test(outputPath)) failures.push(`targets.${targetName}.outputPath is invalid`);
  if (strings.length + numbers.length === 0) failures.push(`targets.${targetName} has no vocabulary`);

  const fields = new Set();
  for (const [index, entry] of strings.entries()) {
    const item = asRecord(entry, `targets.${targetName}.strings[${index}]`, failures);
    if (!item) continue;
    const field = asString(item.field, `targets.${targetName}.strings[${index}].field`, failures);
    const value = asString(item.value, `targets.${targetName}.strings[${index}].value`, failures);
    if (!field || value === null) continue;
    if (!/^[A-Z][A-Z0-9_]*$/.test(field)) failures.push(`targets.${targetName} has invalid field ${JSON.stringify(field)}`);
    if (fields.has(field)) failures.push(`targets.${targetName} has duplicate field ${field}`);
    fields.add(field);
    if (value.includes("\0")) failures.push(`targets.${targetName}.${field} contains NUL`);
  }
  for (const [index, entry] of numbers.entries()) {
    const item = asRecord(entry, `targets.${targetName}.numbers[${index}]`, failures);
    if (!item) continue;
    const field = asString(item.field, `targets.${targetName}.numbers[${index}].field`, failures);
    const kind = asString(item.kind, `targets.${targetName}.numbers[${index}].kind`, failures);
    const value = item.value;
    if (!field || !kind) continue;
    if (!/^[A-Z][A-Z0-9_]*$/.test(field)) failures.push(`targets.${targetName} has invalid field ${JSON.stringify(field)}`);
    if (fields.has(field)) failures.push(`targets.${targetName} has duplicate field ${field}`);
    fields.add(field);
    if (kind !== "int" && kind !== "float") failures.push(`targets.${targetName}.${field} has invalid numeric kind`);
    if (typeof value !== "number" || !Number.isFinite(value)) failures.push(`targets.${targetName}.${field} has non-finite numeric value`);
    if (kind === "int" && !Number.isSafeInteger(value)) failures.push(`targets.${targetName}.${field} is not a safe integer`);
  }
  return targetObject;
}

function stringFieldValue(target, field) {
  const entry = target?.strings?.find((candidate) => candidate?.field === field);
  return typeof entry?.value === "string" ? entry.value : null;
}

function stateValues(target) {
  return new Set((target?.strings ?? [])
    .filter((entry) => typeof entry?.field === "string" && entry.field.startsWith("STATE_"))
    .map((entry) => entry.value));
}

/** Validate descriptor structure without importing the TypeScript source model. */
export function validateDescriptor(descriptor) {
  const failures = [];
  const value = asRecord(descriptor, "descriptor", failures);
  if (!value) return failures;
  if (value.descriptorVersion !== 1) failures.push("descriptorVersion must be 1");
  const identities = asRecord(value.identities, "identities", failures);
  if (identities) {
    const names = ["runtimeObserver", "workbenchAdapter", "workbenchHelperBundle"];
    const identityValues = names.map((name) => asString(identities[name], `identities.${name}`, failures));
    if (identityValues.some((item) => item === "")) {
      failures.push("protocol identities must not be empty");
    }
    if (identityValues.every((item) => item !== null) && new Set(identityValues).size !== identityValues.length) {
      failures.push("runtime, adapter, and helper protocol identities must remain distinct");
    }
  }
  const terminalStates = asArray(value.terminalStates, "terminalStates", failures);
  if (terminalStates) {
    if (terminalStates.length === 0) failures.push("terminalStates must not be empty");
    if (!terminalStates.every((state) => typeof state === "string")) failures.push("terminalStates must contain strings");
    if (new Set(terminalStates).size !== terminalStates.length) failures.push("terminalStates must be unique");
  }
  const targets = asRecord(value.targets, "targets", failures);
  const game = targets ? validateTargetDescriptor(targets.game, "game", value, failures) : null;
  const workbench = targets ? validateTargetDescriptor(targets.workbench, "workbench", value, failures) : null;
  if (game && workbench) {
    if (game.outputPath === workbench.outputPath) failures.push("target output paths must be unique");
    if (game.className === workbench.className) failures.push("target class names must be unique");
  }
  if (game && identities) {
    if (stringFieldValue(game, "RUNTIME_PROTOCOL_VERSION") !== identities.runtimeObserver) {
      failures.push("game runtime protocol field must match identities.runtimeObserver");
    }
    if (stringFieldValue(game, "DIRECTORY_SESSION_ROOT") === null || stringFieldValue(game, "FILE_SESSION_CONTRACT") === null) {
      failures.push("game target must declare reviewed session directory and contract-file fields");
    }
  }
  if (workbench && identities) {
    if (stringFieldValue(workbench, "ADAPTER_PROTOCOL") !== identities.workbenchAdapter) {
      failures.push("workbench adapter protocol field must match identities.workbenchAdapter");
    }
    if (stringFieldValue(workbench, "DIRECTORY_SESSION_ROOT") === null) {
      failures.push("workbench target must declare the reviewed session directory field");
    }
  }
  if (terminalStates && game && workbench) {
    const gameStates = stateValues(game);
    const workbenchStates = stateValues(workbench);
    for (const state of terminalStates) {
      if (typeof state !== "string") continue;
      if (!gameStates.has(state)) failures.push(`game target omits terminal state ${JSON.stringify(state)}`);
      if (!workbenchStates.has(state)) failures.push(`workbench target omits terminal state ${JSON.stringify(state)}`);
    }
  }
  const ledger = asArray(value.backendTuning, "backendTuning", failures);
  if (ledger) {
    const required = [["runtime", 0.001], ["workbench", 0.0001], ["workbench", 0.001]];
    for (const [owner, tuning] of required) {
      if (!ledger.some((entry) => entry && entry.owner === owner && entry.value === tuning &&
        typeof entry.source === "string" && typeof entry.reason === "string" && typeof entry.acceptance === "string")) {
        failures.push(`backendTuning is missing ${owner} ${tuning} evidence`);
      }
    }
    for (const target of [game, workbench].filter(Boolean)) {
      for (const number of target.numbers) {
        if (!ledger.some((entry) => entry && entry.value === number.value)) {
          failures.push(`numeric member ${number.field} has no backendTuning decision`);
        }
      }
    }
    for (const [index, entry] of ledger.entries()) {
      const item = asRecord(entry, `backendTuning[${index}]`, failures);
      if (!item) continue;
      if (item.owner !== "runtime" && item.owner !== "workbench") {
        failures.push(`backendTuning[${index}].owner must be runtime or workbench`);
      }
      if (typeof item.value !== "number" || !Number.isFinite(item.value)) {
        failures.push(`backendTuning[${index}].value must be finite`);
      }
      for (const field of ["source", "reason", "acceptance"]) {
        if (typeof item[field] !== "string" || item[field].length === 0) {
          failures.push(`backendTuning[${index}].${field} must be a non-empty string`);
        }
      }
    }
  }
  return failures;
}

function readDescriptor(root) {
  const path = toAbsolute(root, descriptorRelativePath);
  if (!existsSync(path)) throw new Error(`Descriptor is missing: ${descriptorRelativePath}`);
  try {
    return JSON.parse(readFileSync(path, "utf8"));
  } catch (error) {
    throw new Error(`Descriptor is not valid JSON: ${error instanceof Error ? error.message : String(error)}`);
  }
}

function stripCComments(source) {
  return source.replace(/\/\*[\s\S]*?\*\//g, "").replace(/\/\/[^\r\n]*/g, "");
}

function requireSource(root, relativePath, label, failures) {
  const path = toAbsolute(root, relativePath);
  if (!existsSync(path)) {
    failures.push(`${label} is missing (${relativePath})`);
    return "";
  }
  return readFileSync(path, "utf8");
}

function requireMatch(source, expression, expectation, failures) {
  if (!expression.test(source)) failures.push(expectation);
}

function rejectRawVocabulary(source, values, consumer, failures) {
  const uncommented = stripCComments(source);
  for (const value of values) {
    if (uncommented.includes(`"${value}"`)) {
      failures.push(`${consumer} still spells raw protocol literal ${JSON.stringify(value)}`);
    }
  }
}

function namedSourceSection(source, startMarker, endMarker, consumer, failures) {
  const start = source.indexOf(startMarker);
  const end = start >= 0 ? source.indexOf(endMarker, start + startMarker.length) : -1;
  if (start < 0 || end < 0) {
    failures.push(`${consumer} is missing its documented semantic section`);
    return "";
  }
  return source.slice(start, end);
}

function fieldsWithPrefix(target, prefix) {
  return target.strings
    .filter((entry) => entry.field.startsWith(prefix))
    .map((entry) => ({ field: entry.field, value: entry.value }));
}

function validateRuntimeConsumers(root, descriptor, failures) {
  const target = descriptor.targets.game;
  const job = requireSource(root, "observer/addon/Scripts/Game/ReforgerForgeObserver/RFO_ObserverJob.c", "Game job consumer", failures);
  const session = requireSource(root, "observer/addon/Scripts/Game/ReforgerForgeObserver/RFO_ObserverSession.c", "Game session consumer", failures);
  const service = requireSource(root, "observer/addon/Scripts/Game/ReforgerForgeObserver/RFO_ObserverService.c", "Game service consumer", failures);
  const capabilities = requireSource(root, "observer/addon/Scripts/Game/ReforgerForgeObserver/RFO_ObserverCapabilities.c", "Game capability consumer", failures);
  const mailbox = requireSource(root, "observer/addon/Scripts/Game/ReforgerForgeObserver/RFO_ObserverMailboxTransport.c", "Game mailbox consumer", failures);
  const capture = requireSource(root, "observer/addon/Scripts/Game/ReforgerForgeObserver/RFO_ObserverCapture.c", "Game capture consumer", failures);

  requireMatch(job, /RFO_ObserverProtocol\.RUNTIME_PROTOCOL_VERSION/, "Game command validation must use RFO_ObserverProtocol.RUNTIME_PROTOCOL_VERSION", failures);
  for (const { field } of fieldsWithPrefix(target, "STATE_")) {
    if (field === "STATE_DISPATCHED") continue; // This local enum has no runtime wire return for dispatched.
    requireMatch(job, new RegExp(`RFO_ObserverProtocol\\.${field}`), `Game StateName() must use RFO_ObserverProtocol.${field}`, failures);
  }
  requireMatch(session, /RFO_ObserverProtocol\.RUNTIME_PROTOCOL_VERSION/, "Game session validation must use generated runtime protocol", failures);
  requireMatch(session, /RFO_ObserverProtocol\.DIRECTORY_SESSION_ROOT/, "Game session validation must use generated session directory", failures);
  requireMatch(session, /RFO_ObserverProtocol\.FILE_SESSION_CONTRACT/, "Game session path must use generated contract filename", failures);
  requireMatch(service, /RFO_ObserverProtocol\.RUNTIME_PROTOCOL_VERSION/, "Game wire responses must use generated runtime protocol", failures);
  requireMatch(mailbox, /RFO_ObserverProtocol\.DIRECTORY_SESSION_ROOT/, "Game mailbox paths must use generated session directory", failures);
  requireMatch(capture, /RFO_ObserverProtocol\.DIRECTORY_SESSION_ROOT/, "Game capture path must use generated session directory", failures);
  for (const { field } of fieldsWithPrefix(target, "CAP_")) {
    requireMatch(capabilities, new RegExp(`RFO_ObserverProtocol\\.${field}`), `Game capability insertion must use RFO_ObserverProtocol.${field}`, failures);
  }
  for (const { field, value } of fieldsWithPrefix(target, "ERROR_")) {
    if (service.includes(value)) {
      requireMatch(service, new RegExp(`RFO_ObserverProtocol\\.${field}`), `Game error path must use RFO_ObserverProtocol.${field}`, failures);
    }
  }
  rejectRawVocabulary(service, fieldsWithPrefix(target, "ERROR_").map((entry) => entry.value), "Game service", failures);
  rejectRawVocabulary(capabilities, fieldsWithPrefix(target, "CAP_").map((entry) => entry.value), "Game capabilities", failures);
  rejectRawVocabulary(
    namedSourceSection(job, "string StateName()", "protected bool ValidateView", "Game StateName()", failures),
    fieldsWithPrefix(target, "STATE_").map((entry) => entry.value),
    "Game StateName()",
    failures
  );
  rejectRawVocabulary(session, [
    descriptor.identities.runtimeObserver,
    stringFieldValue(target, "DIRECTORY_SESSION_ROOT"),
    stringFieldValue(target, "FILE_SESSION_CONTRACT"),
  ].filter((value) => typeof value === "string"), "Game session", failures);
  rejectRawVocabulary(service, [descriptor.identities.runtimeObserver], "Game service", failures);
  rejectRawVocabulary(mailbox, [stringFieldValue(target, "DIRECTORY_SESSION_ROOT")].filter((value) => typeof value === "string"), "Game mailbox", failures);
  rejectRawVocabulary(capture, [stringFieldValue(target, "DIRECTORY_SESSION_ROOT")].filter((value) => typeof value === "string"), "Game capture", failures);
}

function validateWorkbenchConsumers(root, descriptor, failures) {
  const target = descriptor.targets.workbench;
  const common = requireSource(root, "observer/workbench-addon/Scripts/WorkbenchGame/EnfusionMCP/EMCP_WB_ObserverCommon.c", "Workbench common consumer", failures);
  const adapter = requireSource(root, "src/workbench/observer-adapter.ts", "TypeScript adapter consumer", failures);
  const workbenchAcceptance = requireSource(root, "scripts/run-workbench-observer-acceptance.ts", "Workbench acceptance consumer", failures);
  const runtimeAcceptance = requireSource(root, "scripts/run-runtime-observer-acceptance.ts", "Runtime acceptance consumer", failures);

  requireMatch(common, /EMCP_WB_ObserverProtocol\.ADAPTER_PROTOCOL/, "Workbench response must use EMCP_WB_ObserverProtocol.ADAPTER_PROTOCOL", failures);
  requireMatch(common, /EMCP_WB_ObserverProtocol\.DIRECTORY_SESSION_ROOT/, "Workbench capture directory must use generated session root", failures);
  for (const { field } of fieldsWithPrefix(target, "STATE_")) {
    requireMatch(common, new RegExp(`EMCP_WB_ObserverProtocol\\.${field}`), `Workbench state path must use EMCP_WB_ObserverProtocol.${field}`, failures);
  }
  for (const { field, value } of fieldsWithPrefix(target, "ERROR_")) {
    if (common.includes(value)) {
      requireMatch(common, new RegExp(`EMCP_WB_ObserverProtocol\\.${field}`), `Workbench error path must use EMCP_WB_ObserverProtocol.${field}`, failures);
    }
  }
  rejectRawVocabulary(common, fieldsWithPrefix(target, "STATE_").map((entry) => entry.value), "Workbench common", failures);
  rejectRawVocabulary(common, fieldsWithPrefix(target, "ERROR_").map((entry) => entry.value), "Workbench common", failures);
  rejectRawVocabulary(common, [
    descriptor.identities.workbenchAdapter,
    stringFieldValue(target, "DIRECTORY_SESSION_ROOT"),
  ].filter((value) => typeof value === "string"), "Workbench common", failures);
  requireMatch(adapter, /from "#observer-protocol\/enforce-contract"/, "TypeScript adapter must import the typed Enforce contract", failures);
  requireMatch(adapter, /WORKBENCH_ADAPTER_PROTOCOL/, "TypeScript adapter schemas must use WORKBENCH_ADAPTER_PROTOCOL", failures);
  requireMatch(adapter, /WORKBENCH_ADAPTER_TERMINAL_STATES/, "TypeScript adapter must use contract terminal states", failures);
  if (adapter.includes("reforger-forge-workbench-observer/1")) failures.push("TypeScript adapter retains a raw adapter protocol literal");
  if (/new Set\s*\(\s*\[\s*["']completed["']/.test(adapter)) failures.push("TypeScript adapter retains a private terminal-state set");
  for (const [source, label] of [[workbenchAcceptance, "Workbench acceptance"], [runtimeAcceptance, "Runtime acceptance"]]) {
    requireMatch(source, /OBSERVER_TERMINAL_STATES/, `${label} must import canonical terminal states`, failures);
    if (/new Set\s*\(\s*\[\s*["']completed["']/.test(source)) failures.push(`${label} retains a private terminal-state set`);
  }
}

export function validateObserverEnforceContract(options = {}) {
  const root = options.root ?? repositoryRoot;
  const selectedTarget = options.target ?? "both";
  if (selectedTarget !== "runtime" && selectedTarget !== "workbench" && selectedTarget !== "both") {
    throw new Error("target must be runtime, workbench, or both");
  }
  let descriptor;
  try {
    descriptor = readDescriptor(root);
  } catch (error) {
    return { descriptor, descriptorFailures: [error instanceof Error ? error.message : String(error)], consumerFailures: [] };
  }
  const descriptorFailures = validateDescriptor(descriptor);
  if (descriptorFailures.length > 0) return { descriptor, descriptorFailures, consumerFailures: [] };

  const selected = selectedTarget === "both" ? targetNames : [selectedTarget];
  for (const targetName of selected) {
    const target = descriptor.targets[targetToDescriptorName[targetName]];
    if (target.outputPath !== expectedOutputPaths[targetName]) {
      descriptorFailures.push(`${targetName} target outputPath must be ${expectedOutputPaths[targetName]}`);
      continue;
    }
    if (target.className !== expectedClassNames[targetName]) {
      descriptorFailures.push(`${targetName} target className must be ${expectedClassNames[targetName]}`);
      continue;
    }
    const path = toAbsolute(root, target.outputPath);
    if (!existsSync(path)) {
      descriptorFailures.push(`${targetName} generated class is missing (${target.outputPath})`);
      continue;
    }
    let expected;
    try {
      expected = renderDescriptorEnforceClass(target);
    } catch (error) {
      descriptorFailures.push(`${targetName} descriptor cannot render C: ${error instanceof Error ? error.message : String(error)}`);
      continue;
    }
    if (normalizeLf(readFileSync(path, "utf8")) !== expected) {
      descriptorFailures.push(`${targetName} descriptor and generated C disagree (${target.outputPath})`);
    }
  }
  if (descriptorFailures.length > 0) return { descriptor, descriptorFailures, consumerFailures: [] };

  const consumerFailures = [];
  if (selected.includes("runtime")) validateRuntimeConsumers(root, descriptor, consumerFailures);
  if (selected.includes("workbench")) validateWorkbenchConsumers(root, descriptor, consumerFailures);
  return { descriptor, descriptorFailures, consumerFailures };
}

function parseArguments(argv) {
  const result = { target: "both", help: false };
  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index];
    if (argument === "--target") {
      const value = argv[index + 1];
      if (!value || value.startsWith("--")) throw new Error("--target requires runtime, workbench, or both");
      result.target = value;
      index += 1;
    } else if (argument === "--help") {
      result.help = true;
    } else {
      throw new Error(`Unknown argument: ${argument}`);
    }
  }
  if (result.target !== "runtime" && result.target !== "workbench" && result.target !== "both") {
    throw new Error("--target must be runtime, workbench, or both");
  }
  return result;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const options = parseArguments(process.argv.slice(2));
    if (options.help) {
      process.stdout.write("Usage: node scripts/validate-observer-enforce-contract.mjs [--target runtime|workbench|both]\n");
    } else {
      const result = validateObserverEnforceContract(options);
      if (result.descriptorFailures.length > 0) {
        process.stderr.write(result.descriptorFailures.map((failure) => `ENFORCE_DESCRIPTOR_DRIFT: ${failure}`).join("\n") + "\n");
        process.exitCode = 1;
      } else if (result.consumerFailures.length > 0) {
        process.stderr.write(result.consumerFailures.map((failure) => `ENFORCE_CONSUMER_DRIFT: ${failure}`).join("\n") + "\n");
        process.exitCode = 1;
      } else {
        process.stdout.write(`Observer Enforce descriptor and consumer contract are current (${options.target}).\n`);
      }
    }
  } catch (error) {
    process.stderr.write(`ENFORCE_DESCRIPTOR_DRIFT: ${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 1;
  }
}
